export function severityBg(sev: AlertSeverity): string {
  switch (sev) {
    case 'critical': return 'rgba(239,68,68,0.14)';
    case 'high':     return 'rgba(251,146,60,0.14)';
    case 'medium':   return 'rgba(250,204,21,0.14)';
    case 'low':      return 'rgba(74,222,128,0.12)';
  }
}

export default function AppearancePage() {
  const router = useRouter();

  const [zoom, setZoomState]       = useState<ZoomLevel>(100);
  const [perPage, setPerPageState] = useState(25);

useEffect(() => {
  const z = readZoom();
  const p = readPerPage();
  setZoomState(z);
  setPerPageState(p);
  setCustomMode(!PER_PAGE_PRESETS.includes(p as typeof PER_PAGE_PRESETS[number]));
  // Apply saved zoom to page
  document.documentElement.style.zoom = (z / 100).toString();
}, []);

function save() {
  localStorage.setItem('mc-appearance', JSON.stringify({ refreshInterval, density, defaultView, showUptime, showIpAddress }));
